tests_dir = os.path.join(ROOT, "tests")
blob_by_file = {}
for f in sorted(os.listdir(tests_dir)):
    if f.startswith("test_") and f.endswith(".py"):
        blob_by_file["tests/" + f] = open(os.path.join(tests_dir, f), encoding="utf-8").read()

selected = set()
for a in sorted(anchors):
    rids = a2r.get(a)
    if not rids:
        print("FALLBACK FULL: anchor %s maps to no matrix row" % a); sys.exit(0)
    for rid in rids:
        r = rows.get(rid)
        if r is None:
            print("FALLBACK FULL: row %s missing" % rid); sys.exit(0)
        if not r["status"].strip().strip("*").strip().startswith("built"):
            print("FALLBACK FULL: row %s status %r not built" % (rid, r["status"])); sys.exit(0)
        owning = r["owning"]
        paths = re.findall(r"[\w./-]*test_\w+\.py", owning)
        stripped = owning
        for p in paths:
            stripped = stripped.replace(p, " ")
            if not os.path.isfile(os.path.join(ROOT, p)):
                print("FALLBACK FULL: row %s cites missing path %s" % (rid, p)); sys.exit(0)
            selected.add(p)
        names = re.findall(r"test_\w+", stripped)
        if not names and not paths:
            print("FALLBACK FULL: row %s owning cell names no test: %r" % (rid, owning)); sys.exit(0)
        for n in names:
            hits = [f for f, blob in blob_by_file.items() if re.search(r"def %s\s*\(" % re.escape(n), blob)]
            if not hits:
                print("FALLBACK FULL: row %s bare token %s resolves to no def" % (rid, n)); sys.exit(0)
            print("   bare %-55s -> %s" % (n, hits))
            selected.update(hits)

ALWAYS = ["tests/test_traceability.py", "tests/test_setup_entry.py", "tests/test_guardrails_unit.py"]
selected.update(ALWAYS)
print("SELECTED (%d):" % len(selected))
for s in sorted(selected):
    print("  ", s)

